@startuml

class Ingredient {
  + Name : string
  + MeasuringUnit : string
  + QuantityInStock : float
}

class Dish {
  + Name : string
  + Identifier : int
}

class IngredientUsage {
  + Quantity : float
}

class Table {
  + Identifier : int
  + MaxPeople : int
}

class Meal {
  + Date : date
  + StartTime : time
  + EndTime : time
}

class Waiter {
  + Identifier : int
  + Name : string
  + Address : string
  + PhoneNumber : string
}

class Client {
  + TaxIdentificationNumber : string
  + Name : string
  + Address : string
}

class MealDish {
  + Quantity : float
}

Dish "1" *-- "1..*" IngredientUsage
Ingredient "1" -- "0..*" IngredientUsage

Dish "1" -- "0..*" MealDish
Meal "1" -- "0..*" MealDish

Meal "0..1" -- "1" Waiter : responsible
Meal "0..1" -- "0..1" Client : consumed by
Meal "0..*" -- "1" Table : takes place at

@enduml

